  }

  final result = <String>[a.first];

  int distance(String s, String t) {
    final rows = s.length + 1;
    final cols = t.length + 1;

    final dp = List.generate(rows, (_) => List<int>.filled(cols, 0));

    for (int i = 0; i < rows; i++) {
      dp[i][0] = i;
    }

    for (int j = 0; j < cols; j++) {
      dp[0][j] = j;
    }

    for (int i = 1; i < rows; i++) {
      for (int j = 1; j < cols; j++) {
        final cost = s[i - 1] == t[j - 1] ? 0 : 1;

        int best = dp[i - 1][j] + 1;
        final ins = dp[i][j - 1] + 1;
        if (ins < best) best = ins;

        final sub = dp[i - 1][j - 1] + cost;
        if (sub < best) best = sub;

        dp[i][j] = best;
      }
    }

    return dp[s.length][t.length];
  }

  for (int i = 1; i < a.length; i++) {
    final previous = result.last;
    final current = a[i];

    if (distance(previous, current) <= 1) {
      result.add(previous);
    } else {
      result.add(current);
    }
  }

  return result;
}

