double fn0(List<List<int>> a) {
  int rows = a.length;
  if (rows == 0) {
    return 0.0;
  }

  int cols = a[0].length;
  int totalWeight = 0;
  double weighted = 0.0;

  for (int i = 0; i < rows; i++) {
    List<int> row = a[i];
    for (int j = 0; j < cols; j++) {
